        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(36, 87, 255, 0.24);
