      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible {
        outline: 3px solid #0f2549;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--accent-strong);
        font-weight: 600;
